import { describe, it, before, beforeEach, afterEach } from "node:test";
import { DockerTestContainer } from "./DockerTestContainer.js";
import assert from "node:assert";

describe("E2E: safe-chain setup-ci command", () => {
  let container;

  before(async () => {
    DockerTestContainer.buildImage();
  });

  beforeEach(async () => {
    container = new DockerTestContainer();
    await container.start();
  });

  afterEach(async () => {
    if (container) {
      await container.stop();
      container = null;
    }
  });

  for (let shell of ["bash", "zsh"]) {
    it(`safe-chain setup-ci wraps npm command with PATH shim after installation for ${shell}`, async () => {
      // setting up the container
      const installationShell = await container.openShell(shell);
      await installationShell.runCommand("safe-chain setup-ci");

      // Add $HOME/.safe-chain/shims to PATH for the test commands
      // Usually this would be done by adding ENV in a Dockerfile, or by
      // the CI system picking up GITHUB_PATH or similar. Here we do it manually
      // to simulate the effect.
      await installationShell.runCommand(
        "echo 'export PATH=\"$HOME/.safe-chain/shims:$PATH\"' >> ~/.zshrc"
      );
      await installationShell.runCommand(
        "echo 'export PATH=\"$HOME/.safe-chain/shims:$PATH\"' >> ~/.bashrc"
      );

      const projectShell = await container.openShell(shell);
      const result = await projectShell.runCommand(
        "npm i axios@1.13.0 --safe-chain-logging=verbose"
      );

      const hasExpectedOutput = result.output.includes("Safe-chain: Scanned");
      assert.ok(
        hasExpectedOutput,
        hasExpectedOutput
          ? "Expected npm command to be wrapped by safe-chain"
          : `Output did not contain "Scanning for malicious packages...": \n${result.output}`
      );
    });
  }

  it("writes to GITHUB_PATH when GITHUB_PATH is set", async () => {
    const installationShell = await container.openShell("zsh");
    await installationShell.runCommand("export GITHUB_PATH=/tmp/github_path");
    await installationShell.runCommand("safe-chain setup-ci");

    const result = await installationShell.runCommand(
      "cat /tmp/github_path | grep '.safe-chain/shims'"
    );

    assert.ok(
      result.output.includes("/root/.safe-chain/shims"),
      `GITHUB_PATH did not contain expected shim path. Output was:\n${result.output}`
    );
  });

  it("writes ##vso[task.prependpath] when TF_BUILD is set", async () => {
    const installationShell = await container.openShell("zsh");
    await installationShell.runCommand("export TF_BUILD=true");

    var result = await installationShell.runCommand("safe-chain setup-ci");

    assert.ok(
      result.output.includes("##vso[task.prependpath]/root/.safe-chain/shims"),
      `TF_BUILD did not contain expected prepend path. Output was:\n${result.output}`
    );
  });
});

import { describe, it, beforeEach, afterEach, mock } from "node:test";
import assert from "node:assert";
import { tmpdir } from "node:os";
import fs from "node:fs";
import path from "path";

describe("Setup CI shell integration", () => {
  let mockShimsDir;
  let mockTemplateDir;
  let setupCi;
  let mockHomeDir;
  let mockPlatform;

  beforeEach(async () => {
    mockPlatform = "linux";
    // Create temporary directories for testing
    mockHomeDir = path.join(tmpdir(), `test-home-${Date.now()}`);
    mockShimsDir = path.join(mockHomeDir, ".safe-chain", "shims");
    mockTemplateDir = path.join(tmpdir(), `test-templates-${Date.now()}`);

    // Create template directories and files
    fs.mkdirSync(path.join(mockTemplateDir, "path-wrappers", "templates"), { recursive: true });
    fs.writeFileSync(
      path.join(mockTemplateDir, "path-wrappers", "templates", "unix-wrapper.template.sh"),
      "#!/bin/bash\n# Template for {{PACKAGE_MANAGER}}\n_safe_chain_shims=$(CDPATH= cd -- \"$(dirname -- \"$0\")\" 2>/dev/null && pwd -P)\nexec {{AIKIDO_COMMAND}} \"$@\"\n",
      "utf-8"
    );
    fs.writeFileSync(
      path.join(mockTemplateDir, "path-wrappers", "templates", "windows-wrapper.template.cmd"),
      "@echo off\nset \"SHIM_DIR=%~dp0\"\n{{AIKIDO_COMMAND}} %*\n",
      "utf-8"
    );

    // Mock the ui module
    mock.module("../environment/userInteraction.js", {
      namedExports: {
        ui: {
          writeInformation: () => {},
          emptyLine: () => {},
          writeError: () => {},
        },
      },
    });

    // Mock the helpers module
    mock.module("./helpers.js", {
      namedExports: {
        knownAikidoTools: [
          { tool: "npm", aikidoCommand: "aikido-npm" },
          { tool: "yarn", aikidoCommand: "aikido-yarn" },
        ],
        getPackageManagerList: () => "npm, yarn",
      },
    });

    mock.module("../config/safeChainDir.js", {
      namedExports: {
        getShimsDir: () => mockShimsDir,
        getBinDir: () => path.join(mockHomeDir, ".safe-chain", "bin"),
        getPathWrapperTemplatePath: (_moduleUrl, fileName) =>
          path.join(mockTemplateDir, "path-wrappers", "templates", fileName),
      },
    });

    // Mock os module
    mock.module("os", {
      namedExports: {
        homedir: () => mockHomeDir,
        platform: () => mockPlatform,
        EOL: "\n",
      },
    });

    // Import setupCi module after mocking
    setupCi = (await import("./setup-ci.js")).setupCi;
  });

  afterEach(() => {
    // Clean up test directories
    if (fs.existsSync(mockShimsDir)) {
      fs.rmSync(mockShimsDir, { recursive: true, force: true });
    }
    if (fs.existsSync(mockHomeDir)) {
      fs.rmSync(mockHomeDir, { recursive: true, force: true });
    }
    if (fs.existsSync(mockTemplateDir)) {
      fs.rmSync(mockTemplateDir, { recursive: true, force: true });
    }

    // Reset mocks
    mock.reset();
    mockPlatform = "linux";
  });

  describe("setupCi", () => {
    it("should create shims directory and Unix shims", async () => {
      await setupCi();

      // Check if shims directory was created
      assert.ok(fs.existsSync(mockShimsDir), "Shims directory should exist");

      // Check if npm shim was created
      const npmShimPath = path.join(mockShimsDir, "npm");
      assert.ok(fs.existsSync(npmShimPath), "npm shim should exist");

      // Check if yarn shim was created
      const yarnShimPath = path.join(mockShimsDir, "yarn");
      assert.ok(fs.existsSync(yarnShimPath), "yarn shim should exist");

      // Check content of npm shim
      const npmShimContent = fs.readFileSync(npmShimPath, "utf-8");
      assert.ok(npmShimContent.includes("aikido-npm"), "npm shim should contain aikido-npm");
      assert.ok(npmShimContent.includes("#!/bin/bash"), "npm shim should have bash shebang");
      assert.ok(
        npmShimContent.includes("_safe_chain_shims=$(CDPATH= cd -- \"$(dirname -- \"$0\")\" 2>/dev/null && pwd -P)"),
        "npm shim should derive the shims directory from its own location",
      );
    });

    it("should create Windows .cmd shims on win32 platform", async () => {
      // Change platform for this test
      mockPlatform = "win32";

      await setupCi();

      // Check if shims directory was created
      assert.ok(fs.existsSync(mockShimsDir), "Shims directory should exist");

      // Check if .cmd files were created instead of Unix scripts
      const npmShimPath = path.join(mockShimsDir, "npm.cmd");
      assert.ok(fs.existsSync(npmShimPath), "npm.cmd shim should exist");

      const yarnShimPath = path.join(mockShimsDir, "yarn.cmd");
      assert.ok(fs.existsSync(yarnShimPath), "yarn.cmd shim should exist");

      // Check content of npm.cmd shim
      const npmShimContent = fs.readFileSync(npmShimPath, "utf-8");
      assert.ok(npmShimContent.includes("aikido-npm"), "npm.cmd should contain aikido-npm");
      assert.ok(npmShimContent.includes("@echo off"), "npm.cmd should have Windows batch header");
      assert.ok(npmShimContent.includes("%*"), "npm.cmd should use Windows argument passing");
      assert.ok(
        npmShimContent.includes('set "SHIM_DIR=%~dp0"'),
        "npm.cmd should derive the shims directory from its own location",
      );

      // Verify Unix shims were NOT created
      const unixNpmShim = path.join(mockShimsDir, "npm");
      assert.ok(!fs.existsSync(unixNpmShim), "Unix npm shim should not exist on Windows");
    });
  });
});

{
  "name": "security-scanner",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Multi-engine security scanner: runs OSS scanners across selected repos, normalizes findings to a common schema, and syncs them to GitHub issues.",
  "bin": {
    "security-scanner": "src/index.mjs"
  },
  "scripts": {
    "test": "node --test test/*.test.mjs"
  },
  "engines": {
    "node": ">=20"
  }
}

import test from "node:test";
import assert from "node:assert/strict";

import { createClient, isRetryableResponse, retryDelayMs } from "../src/issues.mjs";

/** Minimal stand-in for a fetch Response. */
function response(status, { headers = {}, body = {}, text = "" } = {}) {
  return {
    status,
    ok: status >= 200 && status < 300,
    headers: { get: (key) => headers[key.toLowerCase()] ?? null },
    json: async () => body,
    text: async () => text,
  };
}

/** Records how long each backoff waited without actually waiting. */
function recorder() {
  const waits = [];
  return { waits, sleep: async (ms) => void waits.push(ms) };
}

test("a spent rate limit is recognized as 403 as well as 429", () => {
  // GitHub returns 403 with remaining=0 for the primary limit. Treating only
  // 429 as rate limiting would turn the common case into a hard failure.
  assert.ok(isRetryableResponse(response(429)));
  assert.ok(
    isRetryableResponse(response(403, { headers: { "x-ratelimit-remaining": "0" } }))
  );
  assert.ok(isRetryableResponse(response(502)));
});

test("ordinary client errors are not retried", () => {
  assert.ok(!isRetryableResponse(response(404)));
  assert.ok(!isRetryableResponse(response(422)));
  // A 403 with quota left is a permissions problem; retrying cannot fix it.
  assert.ok(
    !isRetryableResponse(response(403, { headers: { "x-ratelimit-remaining": "42" } }))
  );
});

test("retry-after wins over our own guess", () => {
  const delay = retryDelayMs(response(429, { headers: { "retry-after": "7" } }), 0);
  assert.equal(delay, 7000);
});

test("a spent limit waits until the reset moment", () => {
  const now = 1_000_000;
  const delay = retryDelayMs(
    response(403, {
      headers: { "x-ratelimit-remaining": "0", "x-ratelimit-reset": String((now + 30_000) / 1000) },
    }),
    0,
    now
  );

  assert.equal(delay, 30_000);
});

test("backoff grows exponentially and is capped", () => {
  const plain = response(500);
  assert.equal(retryDelayMs(plain, 0), 1000);
  assert.equal(retryDelayMs(plain, 1), 2000);
  assert.equal(retryDelayMs(plain, 2), 4000);
  assert.equal(retryDelayMs(plain, 20), 60_000, "must not grow without bound");
});

test("a rate-limited request succeeds after backing off", async () => {
  const { waits, sleep } = recorder();
  let calls = 0;

  const fetchImpl = async () => {
    calls += 1;
    return calls < 3
      ? response(429, { headers: { "retry-after": "2" } })
      : response(200, { body: { ok: true } });
  };

  const client = createClient("t", fetchImpl, { sleep });
  assert.deepEqual(await client.request("GET", "/x"), { ok: true });
  assert.equal(calls, 3);
  assert.deepEqual(waits, [2000, 2000]);
});

test("a transient network error is retried", async () => {
  const { sleep } = recorder();
  let calls = 0;

  const fetchImpl = async () => {
    calls += 1;
    if (calls === 1) throw new Error("ECONNRESET");
    return response(200, { body: { ok: true } });
  };

  const client = createClient("t", fetchImpl, { sleep });
  assert.deepEqual(await client.request("GET", "/x"), { ok: true });
  assert.equal(calls, 2);
});

test("a 404 fails immediately without burning attempts", async () => {
  const { waits, sleep } = recorder();
  let calls = 0;

  const fetchImpl = async () => {
    calls += 1;
    return response(404, { text: "Not Found" });
  };

  const client = createClient("t", fetchImpl, { sleep });
  await assert.rejects(() => client.request("GET", "/x"), /404/);
  assert.equal(calls, 1, "a 404 is not transient");
  assert.deepEqual(waits, []);
});

test("gives up after the attempt limit rather than looping forever", async () => {
  const { sleep } = recorder();
  let calls = 0;

  const fetchImpl = async () => {
    calls += 1;
    return response(503, { text: "unavailable" });
  };

  const client = createClient("t", fetchImpl, { sleep, maxAttempts: 3 });
  await assert.rejects(() => client.request("GET", "/x"), /503/);
  assert.equal(calls, 3);
});

test("refuses to idle for a far-off rate limit reset", async () => {
  // Sleeping an hour in CI burns runner minutes and hides the problem.
  const now = 1_000_000;
  const { waits, sleep } = recorder();

  const fetchImpl = async () =>
    response(403, {
      headers: {
        "x-ratelimit-remaining": "0",
        "x-ratelimit-reset": String((now + 3_600_000) / 1000),
      },
    });

  const client = createClient("t", fetchImpl, { sleep, now: () => now });
  await assert.rejects(
    () => client.request("GET", "/x"),
    /rate limited until .* longer than this run is willing to wait/s
  );
  assert.deepEqual(waits, [], "must not sleep at all in this case");
});

test("pagination inherits the retry behaviour", async () => {
  const { sleep } = recorder();
  let calls = 0;

  const fetchImpl = async () => {
    calls += 1;
    if (calls === 1) return response(429, { headers: { "retry-after": "1" } });
    return response(200, { body: [] });
  };

  const client = createClient("t", fetchImpl, { sleep });
  assert.deepEqual(await client.paginate("/repos/a/b/issues"), []);
  assert.equal(calls, 2);
});

import chalk from "chalk";
import { ui } from "../environment/userInteraction.js";
import { getPackageManagerList, knownAikidoTools } from "./helpers.js";
import {
  getShimsDir,
  getBinDir,
  getPathWrapperTemplatePath,
} from "../config/safeChainDir.js";
import fs from "fs";
import os from "os";
import path from "path";

/**
 * Loops over the detected shells and calls the setup function for each.
 */
export async function setupCi() {
  ui.writeInformation(
    chalk.bold("Setting up shell aliases.") +
      ` This will wrap safe-chain around ${getPackageManagerList()}.`
  );
  ui.emptyLine();

  const shimsDir = getShimsDir();
  const binDir = getBinDir();
  // Create the shims directory if it doesn't exist
  if (!fs.existsSync(shimsDir)) {
    fs.mkdirSync(shimsDir, { recursive: true });
  }

  createShims(shimsDir);
  ui.writeInformation(`Created shims in ${shimsDir}`);
  modifyPathForCi(shimsDir, binDir);
  ui.writeInformation(`Added shims directory to PATH for CI environments.`);
}

/**
 * @param {string} shimsDir
 *
 * @returns {void}
 */
function createUnixShims(shimsDir) {
  // Read the template file
  const templatePath = getPathWrapperTemplatePath(import.meta.url, "unix-wrapper.template.sh");

  if (!fs.existsSync(templatePath)) {
    ui.writeError(`Template file not found: ${templatePath}`);
    return;
  }

  const template = fs.readFileSync(templatePath, "utf-8");

  // Create a shim for each tool
  let created = 0;
  for (const toolInfo of getToolsToSetup()) {
    const shimContent = template
      .replaceAll("{{PACKAGE_MANAGER}}", toolInfo.tool)
      .replaceAll("{{AIKIDO_COMMAND}}", toolInfo.aikidoCommand);

    const shimPath = path.join(shimsDir, toolInfo.tool);
    fs.writeFileSync(shimPath, shimContent, "utf-8");

    // Make the shim executable on Unix systems
    fs.chmodSync(shimPath, 0o755);
    created++;
  }

  ui.writeInformation(`Created ${created} Unix shim(s) in ${shimsDir}`);
}

/**
 * @param {string} shimsDir
 *
 * @returns {void}
 */
function createWindowsShims(shimsDir) {
  // Read the template file
  const templatePath = getPathWrapperTemplatePath(import.meta.url, "windows-wrapper.template.cmd");

  if (!fs.existsSync(templatePath)) {
    ui.writeError(`Windows template file not found: ${templatePath}`);
    return;
  }

  const template = fs.readFileSync(templatePath, "utf-8");

  // Create a shim for each tool
  let created = 0;
  for (const toolInfo of getToolsToSetup()) {
    const shimContent = template
      .replaceAll("{{PACKAGE_MANAGER}}", toolInfo.tool)
      .replaceAll("{{AIKIDO_COMMAND}}", toolInfo.aikidoCommand);

    const shimPath = `${shimsDir}/${toolInfo.tool}.cmd`;
    fs.writeFileSync(shimPath, shimContent, "utf-8");
    created++;
  }

  ui.writeInformation(`Created ${created} Windows shim(s) in ${shimsDir}`);
}

/**
 * @param {string} shimsDir
 *
 * @returns {void}
 */
function createShims(shimsDir) {
  if (os.platform() === "win32") {
    createWindowsShims(shimsDir);
  } else {
    createUnixShims(shimsDir);
  }
}

/**
 * @param {string} shimsDir
 * @param {string} binDir
 *
 * @returns {void}
 */
function modifyPathForCi(shimsDir, binDir) {
  if (process.env.GITHUB_PATH) {
    // In GitHub Actions, append the shims directory to GITHUB_PATH
    fs.appendFileSync(
      process.env.GITHUB_PATH,
      shimsDir + os.EOL + binDir + os.EOL,
      "utf-8"
    );
    ui.writeInformation(
      `Added shims directory to GITHUB_PATH for GitHub Actions.`
    );
  }

  if (process.env.TF_BUILD) {
    // In Azure Pipelines, prepending the path is done via a logging command:
    //  ##vso[task.prependpath]/path/to/add
    // Logging this to stdout will cause the Azure Pipelines agent to pick it up
    ui.writeInformation("##vso[task.prependpath]" + shimsDir);
    ui.writeInformation("##vso[task.prependpath]" + binDir);
  }

  if (process.env.BASH_ENV) {
    // In CircleCI, persisting PATH across steps is done by appending shell exports
    // to the file referenced by BASH_ENV. CircleCI sources this file for 'run' each step.
    const exportLine = `export PATH="${shimsDir}:${binDir}:$PATH"` + os.EOL;
    fs.appendFileSync(process.env.BASH_ENV, exportLine, "utf-8");
    ui.writeInformation(`Added shims directory to BASH_ENV for CircleCI.`);
  }
}

function getToolsToSetup() {
  return knownAikidoTools;
}

