import { describe, it, before, beforeEach, afterEach } from "node:test";
import { DockerTestContainer } from "./DockerTestContainer.js";
import assert from "node:assert";

describe("E2E: safe-chain setup command", () => {
  let container;

  before(async () => {
    DockerTestContainer.buildImage();
  });

  beforeEach(async () => {
    container = new DockerTestContainer();
    await container.start();
  });

  afterEach(async () => {
    if (container) {
      await container.stop();
      container = null;
    }
  });

  for (let shell of ["bash", "zsh"]) {
    it(`safe-chain setup wraps npm command after installation for ${shell}`, async () => {
      // setting up the container
      const installationShell = await container.openShell(shell);
      await installationShell.runCommand("safe-chain setup");

      const projectShell = await container.openShell(shell);
      await projectShell.runCommand("cd /testapp");
      const result = await projectShell.runCommand(
        "npm i axios@1.13.0 --safe-chain-logging=verbose"
      );

      const hasExpectedOutput = result.output.includes("Safe-chain: Scanned");
      assert.ok(
        hasExpectedOutput,
        hasExpectedOutput
          ? "Expected npm command to be wrapped by safe-chain"
          : `Output did not contain "Scanning for malicious packages...": \n${result.output}`
      );
    });

    it(`safe-chain teardown unwraps npm command after uninstallation for ${shell}`, async () => {
      // setting up the container
      const installationShell = await container.openShell(shell);
      await installationShell.runCommand("safe-chain setup");
      await installationShell.runCommand("safe-chain teardown");

      const projectShell = await container.openShell(shell);
      await projectShell.runCommand("cd /testapp");
      await projectShell.runCommand("npm i axios@1.13.0");
      const result = await projectShell.runCommand("npm i axios@1.13.0");

      assert.ok(
        !result.output.includes("Scanning for malicious packages..."),
        "Expected npm command to not be wrapped by safe-chain after teardown"
      );
    });
  }
});

import { describe, it } from "node:test";
import assert from "node:assert";
import {
  deriveInstallDirFromExecutablePath,
  getInstalledSafeChainDir,
} from "./installLocation.js";

describe("deriveInstallDirFromExecutablePath", () => {
  it("derives the install dir from a Unix binary path", () => {
    assert.strictEqual(
      deriveInstallDirFromExecutablePath("/usr/local/.safe-chain/bin/safe-chain"),
      "/usr/local/.safe-chain",
    );
  });

  it("derives the install dir from a Windows binary path", () => {
    assert.strictEqual(
      deriveInstallDirFromExecutablePath("C:\\ProgramData\\safe-chain\\bin\\safe-chain.exe"),
      "C:\\ProgramData\\safe-chain",
    );
  });

  it("returns undefined when the executable is not inside a bin directory", () => {
    assert.strictEqual(
      deriveInstallDirFromExecutablePath("/usr/local/.safe-chain/safe-chain"),
      undefined,
    );
  });
});

describe("getInstalledSafeChainDir", () => {
  it("returns undefined for non-packaged executions", () => {
    assert.strictEqual(
      getInstalledSafeChainDir({
        isPackaged: false,
        executablePath: "/usr/local/.safe-chain/bin/safe-chain",
      }),
      undefined,
    );
  });

  it("returns the install dir for packaged executions", () => {
    assert.strictEqual(
      getInstalledSafeChainDir({
        isPackaged: true,
        executablePath: "/usr/local/.safe-chain/bin/safe-chain",
      }),
      "/usr/local/.safe-chain",
    );
  });
});

import { describe, it } from "node:test";
import assert from "node:assert";
import { parsePackagesFromInstallArgs } from "./parsePackagesFromInstallArgs.js";

describe("parsePackagesFromInstallArgs", () => {
  it("should return an empty array for no changes", () => {
    const args = ["install"];

    const result = parsePackagesFromInstallArgs(args);

    assert.deepEqual(result, []);
  });

  it("should return an array of changes for one package", () => {
    const args = ["install", "@jest/transform@29.7.0"];

    const result = parsePackagesFromInstallArgs(args);

    assert.deepEqual(result, [{ name: "@jest/transform", version: "29.7.0" }]);
  });

  it("should return the package in the format @vercel/otel", () => {
    const args = ["install", "@vercel/otel"];

    const result = parsePackagesFromInstallArgs(args);

    assert.deepEqual(result, [{ name: "@vercel/otel", version: "latest" }]);
  });

  it("should return an array of changes for multiple packages", () => {
    const args = ["install", "express@4.17.1", "lodash@4.17.21"];

    const result = parsePackagesFromInstallArgs(args);

    assert.deepEqual(result, [
      { name: "express", version: "4.17.1" },
      { name: "lodash", version: "4.17.21" },
    ]);
  });

  it("should ignore options and return an array of changes", () => {
    const args = [
      "install",
      "--save-dev",
      "express@4.17.1",
      "--save-exact",
      "lodash@4.17.21",
    ];

    const result = parsePackagesFromInstallArgs(args);

    assert.deepEqual(result, [
      { name: "express", version: "4.17.1" },
      { name: "lodash", version: "4.17.21" },
    ]);
  });

  it("should ignore options with parameters and return an array of changes", () => {
    const args = [
      "install",
      "--save-dev",
      "express@4.17.1",
      "--loglevel",
      "error",
      "lodash@4.17.21",
    ];

    const result = parsePackagesFromInstallArgs(args);

    assert.deepEqual(result, [
